                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 0
                            and (yy, xx) not in seen):
                        seen.add((yy, xx))
                        q.append((yy, xx))
            if edge:
                exterior.update(cells)
            else:
                enclosed.append(cells)

    # Fill each enclosed region, leaving its deepest core cell(s) as zero.
    for cells in enclosed:
        cellset = set(cells)
        dist = {}
        q = deque()
        for y, x in cells:
            if any(0 <= y + dy < h and 0 <= x + dx < w
